const nearbyTranslations={tr:["Ayasofya","Kapalıçarşı","Topkapı Sarayı","Mısır Çarşısı"],en:["Hagia Sophia","Grand Bazaar","Topkapı Palace","Spice Bazaar"],de:["Hagia Sophia","Großer Basar","Topkapı-Palast","Gewürzbasar"],fr:["Sainte-Sophie","Grand Bazar","Palais de Topkapı","Bazar aux épices"],es:["Santa Sofía","Gran Bazar","Palacio de Topkapı","Bazar de las Especias"],ru:["Собор Святой Софии","Гранд-базар","Дворец Топкапы","Египетский базар"],ar:["آيا صوفيا","البازار الكبير","قصر توبكابي","سوق التوابل"],az:["Ayasofya","Kapalıçarşı","Topkapı Sarayı","Misir Çarşısı"]};const landmarkHistory={
tr:{
 ayasofya:{title:"Ayasofya",text:"Bugünkü yapı, İmparator I. Justinianus döneminde 532–537 yılları arasında inşa edildi. 1453’te İstanbul’un fethinden sonra camiye dönüştürüldü ve İstanbul’un tarihî yarımadasının en önemli anıtlarından biri olarak günümüze ulaştı.",fact:"532–537 · Doğu Roma / Osmanlı mirası"},
 kapalicarsi:{title:"Kapalıçarşı",text:"Kapalıçarşı’nın temeli Fatih Sultan Mehmed döneminde atıldı. Zamanla bedestenler, hanlar ve dükkânlarla büyüyen çarşı, yüzyıllar boyunca İstanbul’un önemli ticaret merkezlerinden biri oldu.",fact:"Fatih dönemi · Tarihî ticaret merkezi"},
 topkapi:{title:"Topkapı Sarayı",text:"Fatih Sultan Mehmed tarafından 1460–1478 yılları arasında kurulan Topkapı Sarayı, yaklaşık dört yüzyıl boyunca Osmanlı padişahlarının ikametgâhı ve devletin yönetim, eğitim ve sanat merkezlerinden biri oldu.",fact:"1460–1478 · Yaklaşık 4 yüzyıl"},
 misircarsisi:{title:"Mısır Çarşısı",text:"Yeni Cami Külliyesi’nin bir parçası olarak 1660’ta yapımına başlandı ve 1664’te tamamlandı. Baharat ve ticaret geleneğiyle özdeşleşen çarşı, 18. yüzyılın ortalarından itibaren Mısır Çarşısı adıyla anıldı.",fact:"1660–1664 · Yeni Cami Külliyesi"}
},
en:{
 ayasofya:{title:"Hagia Sophia",text:"The present building was commissioned by Emperor Justinian I and built between 532 and 537. After the Ottoman conquest of Constantinople in 1453, it was converted into a mosque and remains one of the defining monuments of Istanbul’s Historic Peninsula.",fact:"532–537 · Byzantine & Ottoman heritage"},
 kapalicarsi:{title:"Grand Bazaar",text:"The Grand Bazaar began under Sultan Mehmed II after the conquest and expanded over the centuries into a vast covered commercial district. It became one of Istanbul’s historic centres for trade and craftsmanship.",fact:"Ottoman era · Historic trading centre"},
 topkapi:{title:"Topkapı Palace",text:"Built by Sultan Mehmed II between 1460 and 1478, Topkapı Palace served for nearly four centuries as the Ottoman sultans’ residence and as a centre of government, education and art.",fact:"1460–1478 · Nearly four centuries"},
 misircarsisi:{title:"Spice Bazaar",text:"Built as part of the New Mosque complex, construction began in 1660 and was completed in 1664. Its long association with spices and goods arriving through Istanbul’s trade routes gave the bazaar its familiar name.",fact:"1660–1664 · Part of the New Mosque complex"}
},
de:{
 ayasofya:{title:"Hagia Sophia",text:"Das heutige Bauwerk wurde unter Kaiser Justinian I. zwischen 532 und 537 errichtet. Nach der osmanischen Eroberung 1453 wurde es in eine Moschee umgewandelt und prägt bis heute die historische Halbinsel Istanbuls.",fact:"532–537 · Byzantinisches & osmanisches Erbe"},
 kapalicarsi:{title:"Großer Basar",text:"Der Große Basar entstand nach der Eroberung unter Sultan Mehmed II. und wuchs über Jahrhunderte zu einem weitläufigen Handelsviertel mit überdachten Gassen, Bedesten und Geschäften.",fact:"Osmanische Zeit · Historisches Handelszentrum"},
 topkapi:{title:"Topkapı-Palast",text:"Der von Sultan Mehmed II. zwischen 1460 und 1478 errichtete Palast war fast vier Jahrhunderte Residenz der osmanischen Sultane sowie Zentrum von Regierung, Bildung und Kunst.",fact:"1460–1478 · Fast vier Jahrhunderte"},
 misircarsisi:{title:"Ägyptischer Basar",text:"Der Basar wurde als Teil des Komplexes der Neuen Moschee ab 1660 errichtet und 1664 vollendet. Seine Verbindung mit Gewürzen und Handelswaren prägte seinen heutigen Namen.",fact:"1660–1664 · Teil des Yeni-Moschee-Komplexes"}
},
fr:{
 ayasofya:{title:"Sainte-Sophie",text:"L’édifice actuel fut commandé par l’empereur Justinien Ier et construit entre 532 et 537. Après la conquête ottomane de 1453, il fut transformé en mosquée et demeure un monument majeur de la péninsule historique d’Istanbul.",fact:"532–537 · Héritage byzantin et ottoman"},
 kapalicarsi:{title:"Grand Bazar",text:"Le Grand Bazar a commencé sous le règne de Mehmed II après la conquête et s’est développé pendant des siècles en un vaste centre commercial couvert.",fact:"Époque ottomane · Centre commercial historique"},
 topkapi:{title:"Palais de Topkapı",text:"Construit par Mehmed II entre 1460 et 1478, le palais de Topkapı fut pendant près de quatre siècles la résidence des sultans ottomans et un centre du gouvernement, de l’éducation et des arts.",fact:"1460–1478 · Près de quatre siècles"},
 misircarsisi:{title:"Bazar aux épices",text:"Construit dans le complexe de la Nouvelle Mosquée à partir de 1660 et achevé en 1664, le bazar est historiquement associé aux épices et au commerce d’Istanbul.",fact:"1660–1664 · Complexe de la Nouvelle Mosquée"}
},
es:{
 ayasofya:{title:"Santa Sofía",text:"El edificio actual fue encargado por el emperador Justiniano I y construido entre 532 y 537. Tras la conquista otomana de 1453 se convirtió en mezquita y sigue siendo uno de los monumentos principales de la península histórica de Estambul.",fact:"532–537 · Herencia bizantina y otomana"},
 kapalicarsi:{title:"Gran Bazar",text:"El Gran Bazar comenzó durante el reinado de Mehmed II tras la conquista y creció durante siglos hasta convertirse en un gran centro comercial cubierto.",fact:"Época otomana · Centro histórico de comercio"},
 topkapi:{title:"Palacio de Topkapı",text:"Construido por Mehmed II entre 1460 y 1478, el Palacio de Topkapı fue durante casi cuatro siglos residencia de los sultanes otomanos y centro de gobierno, educación y arte.",fact:"1460–1478 · Casi cuatro siglos"},
 misircarsisi:{title:"Bazar de las Especias",text:"Construido como parte del complejo de la Nueva Mezquita, comenzó en 1660 y terminó en 1664. Su relación histórica con las especias y el comercio de Estambul dio forma a su nombre.",fact:"1660–1664 · Complejo de la Nueva Mezquita"}
},
ru:{
 ayasofya:{title:"Собор Святой Софии",text:"Современное здание было построено по заказу императора Юстиниана I в 532–537 годах. После завоевания Константинополя османами в 1453 году оно стало мечетью и остаётся одним из главных памятников исторического полуострова Стамбула.",fact:"532–537 · Византийское и османское наследие"},
 kapalicarsi:{title:"Гранд-базар",text:"Гранд-базар начал формироваться при султане Мехмеде II после завоевания города и на протяжении веков расширялся как крупный крытый торговый центр.",fact:"Османская эпоха · Исторический торговый центр"},
 topkapi:{title:"Дворец Топкапы",text:"Дворец был построен султаном Мехмедом II в 1460–1478 годах и почти четыре века служил резиденцией османских султанов и центром управления, образования и искусства.",fact:"1460–1478 · Почти четыре века"},
 misircarsisi:{title:"Египетский базар",text:"Базар был построен как часть комплекса Новой мечети: строительство началось в 1660 году и завершилось в 1664-м. Его история тесно связана с торговлей специями.",fact:"1660–1664 · Комплекс Новой мечети"}
},
ar:{
 ayasofya:{title:"آيا صوفيا",text:"شُيّد المبنى الحالي في عهد الإمبراطور جستنيان بين عامي 532 و537. وبعد فتح القسطنطينية عام 1453 تحوّل إلى مسجد، ولا يزال من أبرز معالم شبه جزيرة إسطنبول التاريخية.",fact:"532–537 · تراث بيزنطي وعثماني"},
 kapalicarsi:{title:"البازار الكبير",text:"بدأ البازار الكبير في عهد السلطان محمد الثاني بعد فتح المدينة، وتوسع عبر القرون ليصبح مركزاً تجارياً تاريخياً واسعاً ومغطى.",fact:"العصر العثماني · مركز تجاري تاريخي"},
 topkapi:{title:"قصر توبكابي",text:"بُني القصر بأمر السلطان محمد الثاني بين عامي 1460 و1478، وظل قرابة أربعة قرون مقر إقامة السلاطين العثمانيين ومركزاً للحكم والتعليم والفنون.",fact:"1460–1478 · قرابة أربعة قرون"},
 misircarsisi:{title:"سوق التوابل",text:"أُنشئ السوق ضمن مجمع المسجد الجديد، وبدأ بناؤه عام 1660 واكتمل عام 1664. ارتبط اسمه تاريخياً بتجارة التوابل والسلع القادمة عبر طرق إسطنبول التجارية.",fact:"1660–1664 · ضمن مجمع المسجد الجديد"}
},
az:{
 ayasofya:{title:"Ayasofya",text:"Bugünkü bina imperator I Yustinianın dövründə 532–537-ci illərdə inşa edilib. 1453-cü ildə İstanbulun fəthindən sonra məscidə çevrilib və tarixi yarımadanın əsas abidələrindən biri olaraq qalır.",fact:"532–537 · Bizans və Osmanlı irsi"},
 kapalicarsi:{title:"Kapalıçarşı",text:"Kapalıçarşı İstanbulun fəthindən sonra Sultan II Mehmed dövründə formalaşmağa başlayıb və əsrlər ərzində böyük örtülü ticarət mərkəzinə çevrilib.",fact:"Osmanlı dövrü · Tarixi ticarət mərkəzi"},
 topkapi:{title:"Topkapı Sarayı",text:"Sultan II Mehmed tərəfindən 1460–1478-ci illərdə inşa edilən Topkapı Sarayı təxminən dörd əsr Osmanlı sultanlarının iqamətgahı, idarəetmə, təhsil və incəsənət mərkəzi olub.",fact:"1460–1478 · Təxminən dörd əsr"},
 misircarsisi:{title:"Misir Çarşısı",text:"Yeni Məscid külliyəsinin bir hissəsi kimi 1660-cı ildə tikintisinə başlanıb və 1664-cü ildə tamamlanıb. Çarşı tarixən ədviyyat və ticarətlə sıx bağlıdır.",fact:"1660–1664 · Yeni Məscid külliyəsi"}
}};
