function renderServices(){
 const root=document.getElementById("serviceGrid");if(!root)return;
 const catalog=serviceCatalog[lang]||serviceCatalog.en,group=catalog[mode]||catalog.woman;
 const lead=document.querySelector("[data-i18n=\"services.lead\"]");if(lead)lead.textContent=group.lead;
 const title=document.querySelector("[data-i18n=\"services.title\"]");if(title)title.innerHTML=group.title;
 const label=document.getElementById("modeLabel");if(label)label.textContent=modeWords[lang]?.[mode]||mode.toUpperCase();
  root.innerHTML=group.categories.map(cat=>`<article class="service-directory-card glass-panel reveal" id="service-${cat.key}"><div class="service-directory-top"><span></span><a class="service-arrow-link service-directory-arrow" href="#service-${cat.key}" aria-label="${cat.title}"><img src="assets/icons/service-arrow-circle.svg" alt="" aria-hidden="true"></a></div><h3>${cat.title}</h3><ul class="service-category-list">${cat.items.map(item=>typeof item==="string"?`<li>${item}</li>`:`<li class="service-rich-item"><strong>${item.name}</strong><small>${item.desc}</small></li>`).join("")}</ul></article>`).join("");
 observeReveals();
}
function applyLanguage(){renderServicePreview();const servicePageTitles={tr:"Hizmetler | Salon White Eminönü–Sirkeci",en:"Services | Salon White Eminonu–Sirkeci",de:"Leistungen | Salon White Eminonu–Sirkeci",fr:"Services | Salon White Eminonu–Sirkeci",es:"Servicios | Salon White Eminonu–Sirkeci",ru:"Услуги | Salon White Eminonu–Sirkeci",ar:"الخدمات | Salon White EMINONU–SIRKECI",az:"Xidmətlər | Salon White Eminonu–Sirkeci"};const t=translations[lang]||translations.en;if(document.body?.dataset.servicePage==="true")document.title=servicePageTitles[lang]||servicePageTitles.en;const serviceTitle=document.querySelector("[data-i18n=\"services.title\"]");if(serviceTitle)serviceTitle.innerHTML=serviceTitles[lang]?.[mode]||serviceTitles.en[mode];const modeTitle=document.querySelector("[data-i18n=\"services.modeTitle\"]");if(modeTitle)modeTitle.textContent=serviceTitles[lang]?.[mode]||serviceTitles.en[mode];const ht=hoursTranslations[lang]||hoursTranslations.en;document.querySelector("[data-hours-kicker]")&&(document.querySelector("[data-hours-kicker]").textContent=ht.kicker);document.querySelector("[data-hours-title]")&&(document.querySelector("[data-hours-title]").textContent=ht.title);document.querySelector("[data-hours-note]")&&(document.querySelector("[data-hours-note]").textContent=ht.note);document.querySelectorAll("[data-day]").forEach(el=>{el.textContent=ht.days[el.dataset.day]||el.textContent});document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";document.querySelectorAll("[data-i18n]").forEach(el=>{const v=getPath(t,el.dataset.i18n);if(v)el.innerHTML=v;});const lb=document.getElementById("langButton");if(lb)lb.textContent=lang.toUpperCase();localStorage.setItem("salonWhiteLang",lang);const subtitle=document.getElementById("heroSubtitle");if(subtitle)subtitle.textContent=t.hero.subtitle;const title=document.getElementById("heroTitle");if(title)title.innerHTML=lang==="tr"?'<span>Salon</span> White<br><em class="hero-location-main"><span class="hero-location-word hero-location-first">EMİNÖNÜ–</span><span class="hero-location-word hero-location-second">SİRKECİ</span></em>':'<span>Salon</span> White<br><em class="hero-location-main"><span class="hero-location-word hero-location-first">EMINONU–</span><span class="hero-location-word hero-location-second">SIRKECI</span></em>';document.querySelectorAll("[data-mode-switch]").forEach(btn=>{btn.textContent=modeWords[lang]?.[btn.dataset.modeSwitch]||btn.dataset.modeSwitch.toUpperCase();});const nearby=document.getElementById("nearbyList");if(nearby){const names=nearbyTranslations[lang]||nearbyTranslations.en;const keys=["ayasofya","kapalicarsi","topkapi","misircarsisi"];nearby.innerHTML=names.map((x,i)=>`<button type="button" class="nearby-place" data-landmark="${keys[i]}">${x}</button>`).join("");}}
function setMode(next){if(!["woman","man"].includes(next))return;mode=next;document.body.dataset.mode=mode;document.querySelectorAll(".mode-option").forEach(b=>{const active=b.dataset.modeSwitch===mode;b.classList.toggle("active",active);b.setAttribute("aria-pressed",active?"true":"false");});localStorage.setItem("salonWhiteMode",mode);applyLanguage();renderServices();}
window.setMode=setMode;
function setupLandmarkModal(){const list=document.getElementById("nearbyList"),modal=document.getElementById("landmarkModal");if(!list||!modal||list.dataset.bound==="1")return;list.dataset.bound="1";document.body.appendChild(modal);const card=modal.querySelector(".landmark-modal-card"),anchor=document.querySelector('[data-i18n="istanbul.copy"]');const position=()=>{if(!card||!anchor)return;const r=anchor.getBoundingClientRect(),gap=14,maxH=Math.min(window.innerHeight*.36,320),top=Math.max(18,Math.min(window.innerHeight-maxH-18,r.bottom+gap));modal.style.setProperty("--landmark-top",top+"px");};const close=()=>{modal.hidden=true;document.body.classList.remove("landmark-open");modal.style.removeProperty("--landmark-top");};list.addEventListener("click",e=>{const btn=e.target.closest("[data-landmark]");if(!btn)return;const item=(landmarkHistory[lang]||landmarkHistory.en)[btn.dataset.landmark];if(!item)return;document.getElementById("landmarkModalTitle").textContent=item.title;document.getElementById("landmarkModalText").textContent=item.text;document.getElementById("landmarkModalFact").textContent=item.fact;position();modal.hidden=false;document.body.classList.add("landmark-open");});window.addEventListener("resize",()=>{if(!modal.hidden)position();});modal.querySelectorAll("[data-landmark-close]").forEach(el=>el.addEventListener("click",close));document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!modal.hidden)close();});}
function setupModeSwitch(){document.querySelectorAll("[data-mode-switch]").forEach(btn=>{if(btn.dataset.modeBound==="1")return;btn.dataset.modeBound="1";btn.addEventListener("click",()=>setMode(btn.dataset.modeSwitch));});}
function setupMobileMenu(){const button=document.getElementById("menuButton"),menu=document.getElementById("mobileMenu"),langMenu=document.getElementById("langMenu"),langButton=document.getElementById("langButton");if(!button||!menu)return;const close=()=>{menu.classList.remove("open");menu.hidden=true;button.setAttribute("aria-expanded","false");document.body.classList.remove("menu-open");};button.addEventListener("click",e=>{e.stopPropagation();if(langMenu){langMenu.classList.remove("open");}if(langButton){langButton.setAttribute("aria-expanded","false");}const open=!menu.classList.contains("open");if(open){menu.hidden=false;menu.classList.remove("open");requestAnimationFrame(()=>requestAnimationFrame(()=>menu.classList.add("open")));}else{menu.classList.remove("open");setTimeout(()=>{if(!menu.classList.contains("open"))menu.hidden=true},360);}button.setAttribute("aria-expanded",open?"true":"false");document.body.classList.toggle("menu-open",open);});menu.querySelectorAll("a").forEach(a=>a.addEventListener("click",close));document.addEventListener("click",e=>{if(!e.target.closest("#mobileMenu")&&!e.target.closest("#menuButton"))close();});document.addEventListener("keydown",e=>{if(e.key==="Escape")close();});}
function setupLanguage(){const b=document.getElementById("langButton"),m=document.getElementById("langMenu"),mobile=document.getElementById("mobileMenu"),mobileButton=document.getElementById("menuButton");if(!b||!m)return;b.addEventListener("click",e=>{e.stopPropagation();if(mobile){mobile.classList.remove("open");mobile.hidden=true;}if(mobileButton){mobileButton.setAttribute("aria-expanded","false");}const open=!m.classList.contains("open");m.classList.toggle("open",open);b.setAttribute("aria-expanded",open?"true":"false");});m.querySelectorAll("[data-lang]").forEach(x=>x.addEventListener("click",()=>{lang=x.dataset.lang;applyLanguage();renderServices();m.classList.remove("open");b.setAttribute("aria-expanded","false");}));document.addEventListener("click",e=>{if(!e.target.closest(".lang-wrap")){m.classList.remove("open");b.setAttribute("aria-expanded","false");}});}
function setupHeroActionBar(){const bar=document.getElementById("mobileActionBar");if(!bar)return;const sync=()=>{const scroller=document.scrollingElement||document.documentElement;const scrollTop=scroller.scrollTop||window.scrollY||0;const viewport=scroller.clientHeight||window.innerHeight;const total=scroller.scrollHeight;const atEnd=scrollTop+viewport>=total-80;document.body.classList.toggle("page-end",atEnd);};sync();addEventListener("scroll",sync,{passive:true});addEventListener("resize",sync,{passive:true});addEventListener("pageshow",sync,{passive:true});setTimeout(sync,120);}
async function syncManagedImages(){
  try{
    const r=await fetch("/api/images?ts="+Date.now(),{cache:"no-store",credentials:"same-origin"});
    if(!r.ok)return;
    const d=await r.json();
    const files=new Map((d.files||[]).map(x=>[x.name,x]));
    const targets={
      "admin-slider-01-exterior.png":".hero-slider .hero-slide:nth-child(1)",
      "admin-slider-02-interior.png":".hero-slider .hero-slide:nth-child(2)",
      "admin-slider-03-collage.png":".hero-slider .hero-slide:nth-child(3)",
      "admin-atmosphere-01.png":".feature-image-inner",
      "admin-gallery-01-collage.png":".gallery-grid .gallery-card:nth-child(1) img",
      "admin-gallery-02-exterior.png":".gallery-grid .gallery-card:nth-child(2) img",
      "admin-gallery-03-interior.png":".gallery-grid .gallery-card:nth-child(3) img",
      "admin-istanbul-01.png":".istanbul-bg"
    };
    const slots=Object.keys(targets);
    const resolve=(name)=>files.get(name)?.url||null;
    for(const [slot,selector] of Object.entries(targets)){
      const file=files.get(slot);
      if(!file?.url)continue;
      const el=document.querySelector(selector);
      if(!el)continue;
      if(el.tagName==="IMG")el.src=file.url;
      else el.style.backgroundImage="url('"+file.url+"')";
    }
    window.SALON_WHITE_MANAGED_IMAGES={files,targets,resolve};
  }catch(e){}
}
function observeReveals(){if(!revealObserver)revealObserver=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("visible");revealObserver.unobserve(e.target);}}),{threshold:.12});document.querySelectorAll(".reveal:not(.visible)").forEach(e=>revealObserver.observe(e));}
function updateSlide(n){const slides=[...document.querySelectorAll(".hero-slide")];if(!slides.length)return;slides[slide]?.classList.remove("active");slide=(n+slides.length)%slides.length;slides[slide].classList.add("active");const c=document.getElementById("slideCounter");if(c)c.textContent=`0${slide+1} — 03`;}
function stopSlider(){if(slideTimer){clearInterval(slideTimer);slideTimer=null;}}
function startSlider(){stopSlider();if(document.hidden)return;slideTimer=setInterval(()=>{if(!document.hidden)updateSlide(slide+1);},6500);}
document.addEventListener("visibilitychange",()=>{if(document.hidden)stopSlider();else startSlider();});
function forceTopOnEntry(){if(location.hash&&location.hash!=="#top")return;requestAnimationFrame(()=>scrollTo({top:0,left:0,behavior:"auto"}));setTimeout(()=>scrollTo({top:0,left:0,behavior:"auto"}),80);}
function init(){syncManagedImages();const y=document.getElementById("year");if(y)y.textContent=new Date().getFullYear();forceTopOnEntry();document.body.dataset.mode=mode;document.querySelectorAll(".mode-option").forEach(b=>{const active=b.dataset.modeSwitch===mode;b.classList.toggle("active",active);b.setAttribute("aria-pressed",active?"true":"false");});setupModeSwitch();setupLandmarkModal();setupMobileMenu();setupLanguage();setupHeroActionBar();applyLanguage();renderServices();observeReveals();startSlider();}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init();

window.addEventListener("pageshow",()=>{if(!location.hash||location.hash==="#top")scrollTo({top:0,left:0,behavior:"auto"});});
